  "claim": {
    "component_id": "C069",
    "value": "If canary exposure is inadequate, the result should be reported as inconclusive.",
    "scope": "Conditional on exposure inadequacy; the mapping supplies no numerical adequacy threshold.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "CONTEXT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P031 supplies the conditional reporting rule; P030 identifies the canary context."
    }
  },
  "signal_basis": {
    "component_id": "C069_SIGNAL",
    "value": "Canary exposure is inadequate to make the absence of rare delays informative, with the observation window and required exposure specified before evaluation.",
    "scope": "Assessment of canary results for rare export delays under comparable exposure; no numerical exposure requirement is supplied.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P030 explains why insufficient exposure prevents a clean canary from establishing resolution; P031 requires advance specification of exposure and identifies inadequate exposure as grounds for an inconclusive result."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C069_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed for this supported reporting rule."
    }
  },
  "rationale": "Given inadequate exposure, a canary cannot meaningfully establish resolution of a rare delay. Reporting the result as inconclusive is warranted within the claim's explicit conditional bounds.",
  "uncertainty": "The mapping does not quantify adequate exposure, but exposure inadequacy is assumed for this judgment.",
  "anomalies": []
}
